import React, { useRef, useEffect } from "react";
import styled from "styled-components";
import { TextArea } from "@mendix/ide-ui-components/input/TextArea";

const InputWrapper = styled.div`
    position: relative;
    width: 100%;
`;

const StyledTextArea = styled(TextArea)`
    width: 100%;

    & textarea {
        min-height: 24px;
        resize: vertical;
        overflow: auto;
        padding: 3px 4px;
    }
`;

interface TextAreaAutogrowProps {
    ariaLabel: string;
    value: string;
    onChange?: (value: string) => void;
    description?: string;
    readOnly?: boolean;
    rows?: number;
    validate?: (value: string) => true | string | string[] | null | undefined;
    className?: string;
}

const TextAreaAutogrow: React.FC<TextAreaAutogrowProps> = ({
    ariaLabel,
    value,
    onChange,
    description,
    readOnly = false,
    rows = 1,
    validate,
    className,
}) => {
    const wrapperRef = useRef<HTMLDivElement>(null);

    const autoGrow = (element: HTMLTextAreaElement) => {
        element.style.height = "auto";
        element.style.height = element.scrollHeight + 2 + "px"; // adding 2px for the borders
    };

    const handleChange = (value: string) => {
        if (onChange) {
            onChange(value);
        }
    };

    useEffect(() => {
        const textarea = wrapperRef.current?.querySelector("textarea");
        if (textarea) {
            autoGrow(textarea);
        }
    }, [value]);

    return (
        <InputWrapper ref={wrapperRef} className={className}>
            <StyledTextArea
                value={value}
                onChange={handleChange}
                description={description}
                isReadOnly={readOnly}
                aria-label={ariaLabel}
                rows={rows}
                validate={validate}
            />
        </InputWrapper>
    );
};

export default TextAreaAutogrow;
